using NUnit.Framework;
using SIL.FieldWorks.Filters;
using SIL.LCModel;
using FeatVals = System.Collections.Generic.Dictionary<string, string>;

namespace SIL.FieldWorks.XWorks.MorphologyEditor
{
	/// <summary>
	/// Pins which natural classes <see cref="ExcludeAutoGeneratedNaturalClassFilter"/> pass:
	/// every class except a feature-based one generated automatically for a rule.
	/// </summary>
	[TestFixture]
	public class ExcludeAutoGeneratedNaturalClassFilterTests : RuleFormulaVcTestBase
	{
		private ExcludeAutoGeneratedNaturalClassFilter CreateFilter()
		{
			var filter = new ExcludeAutoGeneratedNaturalClassFilter();
			filter.Init(Cache, null);
			return filter;
		}

		private static bool Accepts(RecordFilter filter, ICmObject natClass)
		{
			return filter.Accept(new ManyOnePathSortItem(natClass));
		}

		[Test]
		public void AutoGeneratedClass_IsRejected()
		{
			IPhNCFeatures natClass = AddRuleNamedFeatureNaturalClass("s to n",
				new FeatVals { { "vd", "+" } });

			Assert.That(Accepts(CreateFilter(), natClass), Is.False);
		}

		[Test]
		public void NamedFeatureClass_IsAccepted()
		{
			IPhNCFeatures natClass = AddFeatureNaturalClass("Voiced", "Vd",
				new FeatVals { { "vd", "+" } });

			Assert.That(Accepts(CreateFilter(), natClass), Is.True);
		}

		/// <summary>
		/// A feature-based class the user creates starts with no name, so an unnamed class must
		/// pass for the user to be able to name it.
		/// </summary>
		[Test]
		public void UnnamedFeatureClass_IsAccepted()
		{
			IPhNCFeatures natClass = AddFeatureNaturalClass(null, null,
				new FeatVals { { "vd", "+" } });

			Assert.That(Accepts(CreateFilter(), natClass), Is.True);
		}

		[Test]
		public void SegmentClass_IsAccepted()
		{
			IPhNCSegments natClass = AddSegmentNaturalClass("Vowels", "V");

			Assert.That(Accepts(CreateFilter(), natClass), Is.True);
		}

		/// <summary>
		/// A filter restored from persisted settings is not initialized from a configuration
		/// node; it receives its cache through the Cache setter alone.
		/// </summary>
		[Test]
		public void RestoredFilter_UsesCacheFromSetter()
		{
			IPhNCFeatures natClass = AddRuleNamedFeatureNaturalClass("s to n",
				new FeatVals { { "vd", "+" } });
			var filter = new ExcludeAutoGeneratedNaturalClassFilter { Cache = Cache };

			Assert.That(Accepts(filter, natClass), Is.False);
		}
	}
}
